"""The owner's question list ``docs/open-questions.md`` (v2.1 KD-2), GENERATED by ``b1500 dev gen-index`` (``--check``
compares; part of the gate).

Sources: every live ``TODO(owner): <question>?`` marker in scope (``markers.py``) and the numbered items of the
section "Open questions for the owner" of every debug case (``b1500-debug/cases/*.md``; the template excluded). The
list is grouped by topic (``TOPICS``: by the folder the question lives in, e.g. knowledge = devices, films and lab
practice; stage files = provisional bring-up criteria; debug cases = what the lab has seen), then by file, each
question with a link to its file and, for Markdown, the nearest heading above it. The same question text in several
places is listed once with every link (a debug case's question is about that case and stays with it). The text is a
pure function of the repository files (UTF-8, LF, no timestamps), so ``--check`` compares bytes.
"""


from __future__ import annotations

import re
from dataclasses import dataclass, field
from fnmatch import fnmatch
from pathlib import Path
from typing import Final

from b1500_test_agent.devtools.skills.markdown import MarkdownDoc, parse_markdown
from b1500_test_agent.devtools.skills.markers import CASES_GLOB, relpath, scan_files
from b1500_test_agent.devtools.sync_harness import normalize_text

QUESTIONS_REL: Final = "docs/open-questions.md"
QUESTIONS_MARKER: Final = ("<!-- GENERATED by `uv run b1500 dev gen-index` from the owner questions of the repository "
                           "(TODO(owner) markers, debug-case open questions); answer in the linked file, then "
                           "regenerate -->")
CASE_SECTION: Final = "Open questions for the owner"
TOPICS: Final[tuple[tuple[str, str], ...]] = (
    (".agents/skills/b1500-test/knowledge/*", "Devices, films, processes and lab practice"),
    ("config/duts/*", "DUT profiles"),
    (".agents/skills/b1500-test/cards/*", "Test cards"),
    ("recipes/*", "Recipes"),
    (".agents/skills/b1500-bringup/stages/*", "Bring-up: provisional acceptance criteria"),
    (".agents/skills/b1500-bringup/*", "Bring-up"),
    (CASES_GLOB, "Debug cases: what the lab has seen"),
    (".agents/skills/b1500-debug/*", "Debugging"),
    ("config/*", "Station and policy configuration"),
    ("docs/*", "Documentation"),
    ("src/*", "Code defaults"),
)
"""(path pattern, topic) in list order; the first match wins; anything else goes to "Other"."""
OTHER: Final = "Other"
_NUMBERED = re.compile(r"^(\d+)\.\s+(\S.*)$")


@dataclass(frozen=True)
class Place:
    """Where a question stands: file (repository-relative), line, nearest heading above it (Markdown) and its id."""

    file: str
    line: int
    heading: str = ""
    anchor: str = ""


@dataclass
class OwnerQuestion:
    question: str
    topic: str
    places: list[Place] = field(default_factory=list)


def topic_of(rel: str) -> str:
    return next((topic for pattern, topic in TOPICS if fnmatch(rel, pattern)), OTHER)


def _heading_above(doc: MarkdownDoc | None, line: int) -> tuple[str, str]:
    if doc is None:
        return "", ""
    above = [h for h in doc.headings if h.line <= line]
    return (above[-1].text, above[-1].slug) if above else ("", "")


def _title(root: Path, rel: str, doc: MarkdownDoc | None) -> str:
    """Display title of a file: a case's or card's frontmatter title, the first H1, else the path."""
    if doc is not None:
        if isinstance(doc.front, dict) and isinstance(doc.front.get("title"), str):
            stage = doc.front.get("stage")
            return f"{stage} {doc.front['title']}" if isinstance(stage, str) else str(doc.front["title"])
        first = next((h.text for h in doc.headings if h.level == 1), "")
        if first:
            return first
    return rel


def _parse(root: Path, rel: str, cache: dict[str, MarkdownDoc | None]) -> MarkdownDoc | None:
    if rel not in cache:
        try:
            cache[rel] = parse_markdown(root / rel, rel) if rel.endswith(".md") else None
        except (OSError, UnicodeDecodeError):
            cache[rel] = None
    return cache[rel]


def case_questions(doc: MarkdownDoc) -> list[tuple[int, str]]:
    """(line, text) of the numbered items of the case's "Open questions for the owner" section; an item runs on over
    its indented continuation lines."""
    span = doc.section(CASE_SECTION)
    if span is None:
        return []
    items: list[tuple[int, list[str]]] = []
    for number in range(span[0] + 1, span[1]):
        raw = doc.lines[number - 1]
        match = _NUMBERED.match(raw)
        if match:
            items.append((number, [match.group(2).strip()]))
        elif items and raw.startswith((" ", "\t")) and raw.strip():
            items[-1][1].append(raw.strip())
        elif not raw.strip() and items:
            items.append((0, []))  # a blank line ends the item
    return [(line, " ".join(" ".join(parts).split())) for line, parts in items if line and parts]


def collect_questions(root: Path, recipes_dir: Path | None = None,
                      config_dir: Path | None = None) -> tuple[list[OwnerQuestion], dict[str, str]]:
    """Every owner question under ``root`` (deduplicated by text, in topic, file and line order) and the display
    title of each file that has one."""
    cache: dict[str, MarkdownDoc | None] = {}
    found: list[tuple[str, Place]] = []
    markers, _problems = scan_files(root, recipes_dir, config_dir)
    for marker in markers:
        if marker.kind == "owner" and marker.form == "live":
            heading, anchor = _heading_above(_parse(root, marker.file, cache), marker.line)
            found.append((marker.question, Place(marker.file, marker.line, heading, anchor)))
    cases = root / ".agents" / "skills" / "b1500-debug" / "cases"
    for path in sorted(cases.glob("*.md")) if cases.is_dir() else []:
        rel = relpath(root, path)
        if path.name.startswith("_") or path.is_symlink():
            continue
        doc = _parse(root, rel, cache)
        if doc is None:
            continue
        anchor = next((h.slug for h in doc.headings if h.level == 2 and h.text.strip() == CASE_SECTION), "")
        for line, text in case_questions(doc):
            found.append((text, Place(rel, line, CASE_SECTION, anchor)))
    order = {topic: index for index, (_pattern, topic) in enumerate(TOPICS)}
    found.sort(key=lambda item: (order.get(topic_of(item[1].file), len(order)), item[1].file, item[1].line))
    merged: dict[tuple[str, str, str], OwnerQuestion] = {}
    for text, place in found:
        case = place.file if fnmatch(place.file, CASES_GLOB) else ""  # a case's question is about that case
        key = (topic_of(place.file), " ".join(text.split()).casefold(), case)
        entry = merged.setdefault(key, OwnerQuestion(question=text, topic=key[0]))
        entry.places.append(place)
    titles = {place.file: _title(root, place.file, _parse(root, place.file, cache))
              for entry in merged.values() for place in entry.places}
    return list(merged.values()), titles


def _link(place: Place) -> str:
    target = "../" + place.file + (f"#{place.anchor}" if place.anchor else "")
    label = place.heading or Path(place.file).name
    return f"[{label}]({target.replace(' ', '%20')})"


def render_questions(questions: list[OwnerQuestion], titles: dict[str, str]) -> str:
    """The text of ``docs/open-questions.md``."""
    files = sorted({p.file for q in questions for p in q.places})
    lines = [
        QUESTIONS_MARKER,
        "# Open questions for the owner",
        "",
        "Facts only the owner knows: devices, films, processes, the station and lab practice (v2.1 plan KD-1, KD-2).",
        "Each question stands once in the repository, next to the blank it leaves (a `TODO(owner)` marker followed by",
        "the question; the debug cases number theirs under \"Open questions for the owner\"). Until a question is",
        "answered the agent treats the value as unknown: it says so and asks, and never fills it from general",
        "knowledge, the simulator or an example file. To answer one, write the value and its source (a lab file, a",
        "record, a manual page) into the linked file in place of the marker, then run `uv run b1500 dev gen-index`.",
        "",
        f"{len(questions)} questions in {len(files)} files.",
    ]
    topics = list(dict.fromkeys(q.topic for q in questions))
    for topic in topics:
        lines += ["", f"## {topic}"]
        current = ""
        for entry in (q for q in questions if q.topic == topic):
            first = entry.places[0].file
            if first != current:
                current = first
                lines += ["", f"### {titles.get(first, first)}", "", f"File: `{first}`", ""]
            links = "; ".join(_link(p) if p.file == first else f"`{p.file}` {_link(p)}" for p in entry.places)
            lines.append(f"- {entry.question[:1].upper()}{entry.question[1:]} ({links})")
    if not questions:
        lines += ["", "No open question."]
    return "\n".join(lines) + "\n"


@dataclass(frozen=True)
class QuestionsState:
    """Outcome of writing or checking the question list."""

    path: str
    questions: int
    drift: bool
    written: bool


def gen_questions(root: Path, *, check: bool, recipes_dir: Path | None = None) -> QuestionsState:
    """Write (or with ``check`` compare) ``docs/open-questions.md`` of the repository at ``root``."""
    questions, titles = collect_questions(root, recipes_dir)
    text = render_questions(questions, titles)
    target = root / QUESTIONS_REL
    current = normalize_text(target.read_bytes()) if target.is_file() else None
    drift = current != text
    written = False
    if drift and not check:
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(text.encode("utf-8"))
        written = True
    return QuestionsState(path=QUESTIONS_REL, questions=len(questions), drift=drift, written=written)
